-- Synthetic seeded DEVELOPMENT database only. All fixture writes roll back.
-- Simulated gateway claims test PostgreSQL, not Firebase signature verification.
begin;
create temp table exam_checks(name text primary key);
create temp table exam_fixtures(label text primary key,schedule uuid,assessment uuid,q uuid,correct uuid,wrong uuid,essay uuid);
grant select,insert on exam_checks to authenticated,anon;
grant select on exam_fixtures to authenticated,anon;
create function pg_temp.ok(v boolean,label text) returns void language plpgsql as $$ begin if v is distinct from true then raise exception 'FAILED %',label; end if; insert into pg_temp.exam_checks values(label); end $$;
create function pg_temp.denied(sql text,code text,label text) returns void language plpgsql as $$ declare caught text; begin begin execute sql; exception when others then get stacked diagnostics caught=returned_sqlstate; end; perform pg_temp.ok(caught=code,label||coalesce(' (got '||caught||')',' (no error)')); end $$;
create function pg_temp.claim(n integer) returns void language sql as $$ select set_config('request.jwt.claims',jsonb_build_object('iss','https://gmvouqgjbtbkbhrdruzu.supabase.co/auth/v1','aud','authenticated','role','authenticated','sub','10000000-0000-0000-0000-'||lpad(n::text,12,'0'))::text,true) $$;
create function pg_temp.fixture(label text,maximum integer,duration integer,essay boolean,closes timestamptz default null) returns void language plpgsql as $$
declare aid uuid:=gen_random_uuid(); sid uuid:=gen_random_uuid(); qid uuid:=gen_random_uuid(); yes uuid:=gen_random_uuid(); no uuid:=gen_random_uuid(); eid uuid;
begin
 insert into public.assessments(id,course_id,title,type,status,created_by) values(aid,'30000000-0000-0000-0000-000000000001','Step03A synthetic '||label,'exam','published','10000000-0000-0000-0000-000000000001');
 insert into public.assessment_questions(id,assessment_id,question_type,prompt,points,position) values(qid,aid,'single_choice','Synthetic objective',2,0);
 insert into public.assessment_options(id,question_id,text,position,is_correct) values(yes,qid,'Synthetic correct',0,true),(no,qid,'Synthetic wrong',1,false);
 if essay then eid:=gen_random_uuid(); insert into public.assessment_questions(id,assessment_id,question_type,prompt,points,position) values(eid,aid,'essay','Synthetic written',3,1); end if;
 insert into public.offering_assessments(id,offering_id,assessment_id,max_attempts,time_limit_seconds,published,closes_at,shuffle_questions,shuffle_options) values(sid,'60000000-0000-0000-0000-000000000001',aid,maximum,duration,true,closes,true,true);
 insert into pg_temp.exam_fixtures values(label,sid,aid,qid,yes,no,eid);
end $$;
select pg_temp.fixture('accept',2,60,false);
select pg_temp.fixture('decline',2,null,false);
select pg_temp.fixture('single',1,null,false);
select pg_temp.fixture('perfect',2,60,false);
select pg_temp.fixture('essay',2,60,true,clock_timestamp()+interval '1 hour');
select pg_temp.fixture('essay_only',2,null,true);
delete from public.assessment_options where question_id=(select q from exam_fixtures where label='essay_only');
delete from public.assessment_questions where id=(select q from exam_fixtures where label='essay_only');
select pg_temp.fixture('invalid',2,60,false);
update public.assessment_options set is_correct=false where question_id=(select q from exam_fixtures where label='invalid');
select pg_temp.fixture('private_schedule',1,60,false);
update public.offering_assessments set published=false where id=(select schedule from exam_fixtures where label='private_schedule');
select pg_temp.denied($q$update public.offering_assessments set max_attempts=null where id=(select schedule from pg_temp.exam_fixtures where label='single')$q$,'23514','NULL limit rejected');
select pg_temp.denied($q$update public.offering_assessments set max_attempts=3 where id=(select schedule from pg_temp.exam_fixtures where label='single')$q$,'23514','Third-attempt setting rejected');
select pg_temp.denied($q$update public.offering_assessments set time_limit_seconds=59 where id=(select schedule from pg_temp.exam_fixtures where label='single')$q$,'23514','Sub-minute setting rejected');
set local role authenticated;
select pg_temp.claim(5);
select pg_temp.denied($q$select public.sync_exam_participation((select schedule from pg_temp.exam_fixtures where label='private_schedule'))$q$,'42501','Student cannot sync unpublished schedule');
select pg_temp.denied('select score,max_score,graded_at,graded_by from public.assessment_attempts','42501','Attempt grade columns blocked');
select pg_temp.denied('select * from public.assessment_attempts','42501','Attempt wildcard blocked');
select pg_temp.denied('select id from public.assessment_attempts where score>0','42501','Score predicate blocked');
select pg_temp.denied('select awarded_points,feedback,graded_by,graded_at from public.assessment_responses','42501','Response grades blocked');
select pg_temp.denied('select is_correct from public.assessment_options','42501','Correct flags blocked');
select pg_temp.denied('select * from private.assessment_participations','42501','Participation private');
select pg_temp.denied('select * from private.assessment_question_outcomes','42501','Outcomes private');
select pg_temp.denied($q$select private.start_assessment_attempt_v17((select schedule from pg_temp.exam_fixtures where label='accept'))$q$,'42501','Old start cannot bypass gate');
select pg_temp.denied($q$select public.start_assessment_attempt((select schedule from pg_temp.exam_fixtures where label='invalid'))$q$,'23514','Bad keys block start');
select set_config('exam.a1',public.start_assessment_attempt((select schedule from exam_fixtures where label='accept'))::text,true);
select pg_temp.ok(public.start_assessment_attempt((select schedule from exam_fixtures where label='accept'))=current_setting('exam.a1')::uuid,'Repeated start resumes same UUID');
select set_config('exam.order',public.get_exam_attempt_content(current_setting('exam.a1')::uuid)::text,true);
select pg_temp.ok(public.get_exam_attempt_content(current_setting('exam.a1')::uuid)::text=current_setting('exam.order'),'Shuffle stable across refresh');
select pg_temp.ok(current_setting('exam.order')!~'is_correct|awarded_points|feedback|numeric_key','Run content excludes grading keys');
select public.save_exam_response(current_setting('exam.a1')::uuid,(select q from exam_fixtures where label='accept'),jsonb_build_object('option_ids',jsonb_build_array((select wrong from exam_fixtures where label='accept'))),null,1);
select pg_temp.ok((public.save_exam_response(current_setting('exam.a1')::uuid,(select q from exam_fixtures where label='accept'),jsonb_build_object('option_ids',jsonb_build_array((select wrong from exam_fixtures where label='accept'))),null,1)->>'revision')::integer=2,'Identical save retry is idempotent');
select pg_temp.denied($q$select public.save_exam_response(current_setting('exam.a1')::uuid,(select q from pg_temp.exam_fixtures where label='accept'),null,null,1)$q$,'PT409','Stale differing save rejected');
select public.save_exam_response(current_setting('exam.a1')::uuid,(select q from exam_fixtures where label='accept'),null,null,2);
select pg_temp.ok((select count(*)=0 from public.assessment_responses where attempt_id=current_setting('exam.a1')::uuid),'Clear removes own unsubmitted answer');
select public.save_assessment_response(current_setting('exam.a1')::uuid,(select q from exam_fixtures where label='accept'),jsonb_build_object('option_ids',jsonb_build_array((select wrong from exam_fixtures where label='accept'))));
select public.submit_assessment_attempt(current_setting('exam.a1')::uuid);
select public.submit_assessment_attempt(current_setting('exam.a1')::uuid);
select set_config('exam.state',public.sync_exam_participation((select schedule from exam_fixtures where label='accept'))::text,true);
select pg_temp.ok(current_setting('exam.state')::jsonb->>'attempts_state'='retry_decision_pending','Wrong first paper requires decision');
select pg_temp.ok(current_setting('exam.state')!~'score|incorrect|question_id|feedback|awarded_points','Decision leaks no marks or question identities');
select pg_temp.denied($q$select public.start_assessment_attempt((select schedule from pg_temp.exam_fixtures where label='accept'))$q$,'42501','Direct second start blocked');
select pg_temp.denied($q$select public.get_assessment_results(current_setting('exam.a1')::uuid)$q$,'42501','Pending decision hides result RPC');
select pg_temp.denied($q$select public.get_exam_review((select schedule from pg_temp.exam_fixtures where label='accept'))$q$,'42501','Pending decision hides answer review');
select pg_temp.denied($q$select public.decide_exam_retry((select schedule from pg_temp.exam_fixtures where label='accept'),'accept',0)$q$,'PT409','Stale decision rejected');
select public.decide_exam_retry((select schedule from exam_fixtures where label='accept'),'accept',(current_setting('exam.state')::jsonb->>'revision')::bigint);
select pg_temp.ok(public.decide_exam_retry((select schedule from exam_fixtures where label='accept'),'accept',0)->>'retry_decision'='accepted','Repeated accept returns committed decision');
select pg_temp.denied($q$select public.decide_exam_retry((select schedule from pg_temp.exam_fixtures where label='accept'),'decline',0)$q$,'PT409','Opposing decision rejected');
select set_config('exam.a2',public.start_assessment_attempt((select schedule from exam_fixtures where label='accept'))::text,true);
select pg_temp.ok(public.start_assessment_attempt((select schedule from exam_fixtures where label='accept'))=current_setting('exam.a2')::uuid,'Second start idempotent');
select pg_temp.ok((select count(*)=0 from public.assessment_responses where attempt_id=current_setting('exam.a2')::uuid),'Second paper fresh');
select public.save_assessment_response(current_setting('exam.a2')::uuid,(select q from exam_fixtures where label='accept'),jsonb_build_object('option_ids',jsonb_build_array((select correct from exam_fixtures where label='accept'))));
select public.submit_assessment_attempt(current_setting('exam.a2')::uuid);
select pg_temp.ok((public.get_assessment_results(current_setting('exam.a2')::uuid)->>'score')::numeric=2,'Final attempted objective paper releases total');
select pg_temp.ok(public.get_assessment_results(current_setting('exam.a2')::uuid)->'responses'->0->>'awarded_points' is null,'Per-question result hidden before review');
select pg_temp.denied($q$select public.get_assessment_results(current_setting('exam.a1')::uuid)$q$,'42501','First-paper total remains protected');
select pg_temp.denied($q$select public.start_assessment_attempt((select schedule from pg_temp.exam_fixtures where label='accept'))$q$,'42501','No third start');
select pg_temp.claim(6);
select pg_temp.denied($q$select public.get_assessment_results(current_setting('exam.a2')::uuid)$q$,'42501','Other learner cannot read results');
select pg_temp.denied($q$select public.sync_exam_participation((select schedule from pg_temp.exam_fixtures where label='accept'))$q$,'42501','Unenrolled learner cannot sync');
select pg_temp.claim(3);
select pg_temp.denied($q$select public.get_exam_grading_detail(current_setting('exam.a2')::uuid)$q$,'42501','Other tenant teacher cannot preview grades');
select pg_temp.denied($q$select public.release_exam_review((select schedule from pg_temp.exam_fixtures where label='accept'),'10000000-0000-0000-0000-000000000005',0)$q$,'42501','Other tenant teacher cannot release review');
select pg_temp.claim(2);
select pg_temp.ok(public.get_exam_grading_detail(current_setting('exam.a2')::uuid)->'result'->>'score'='2.000','Assigned instructor sees grade');
select public.release_exam_review((select schedule from exam_fixtures where label='accept'),'10000000-0000-0000-0000-000000000005',(public.get_exam_grading_detail(current_setting('exam.a2')::uuid)->'state'->>'revision')::bigint);
select pg_temp.claim(5);
select pg_temp.ok(jsonb_array_length(public.get_exam_review((select schedule from exam_fixtures where label='accept'))->'questions'->0->'attempts')=2,'Released review retains both histories');
select pg_temp.ok(public.get_exam_review((select schedule from exam_fixtures where label='accept'))->'questions'->0->'correct_option_ids'->>0=(select correct::text from exam_fixtures where label='accept'),'Keys only in authorized released review');
select set_config('exam.decline',public.start_assessment_attempt((select schedule from exam_fixtures where label='decline'))::text,true);
select public.submit_assessment_attempt(current_setting('exam.decline')::uuid);
select pg_temp.ok(public.sync_exam_participation((select schedule from exam_fixtures where label='decline'))->>'attempts_state'='retry_decision_pending','Absent response qualifies as unanswered');
select public.decide_exam_retry((select schedule from exam_fixtures where label='decline'),'decline',(public.sync_exam_participation((select schedule from exam_fixtures where label='decline'))->>'revision')::bigint);
select pg_temp.ok((public.get_assessment_results(current_setting('exam.decline')::uuid)->>'score')::numeric=0,'Absent response scores explicit zero');
select pg_temp.denied($q$select public.start_assessment_attempt((select schedule from pg_temp.exam_fixtures where label='decline'))$q$,'42501','Decline permanent');
select set_config('exam.single',public.start_assessment_attempt((select schedule from exam_fixtures where label='single'))::text,true);
select public.submit_assessment_attempt(current_setting('exam.single')::uuid);
select pg_temp.ok(public.sync_exam_participation((select schedule from exam_fixtures where label='single'))->>'attempts_state'='finalized','One-attempt paper has no retry prompt');
select set_config('exam.perfect',public.start_assessment_attempt((select schedule from exam_fixtures where label='perfect'))::text,true);
select public.save_assessment_response(current_setting('exam.perfect')::uuid,(select q from exam_fixtures where label='perfect'),jsonb_build_object('option_ids',jsonb_build_array((select correct from exam_fixtures where label='perfect'))));
select public.submit_assessment_attempt(current_setting('exam.perfect')::uuid);
select pg_temp.ok(public.sync_exam_participation((select schedule from exam_fixtures where label='perfect'))->>'retry_decision'='not_eligible','Perfect objective has no retry prompt');
select set_config('exam.essay',public.start_assessment_attempt((select schedule from exam_fixtures where label='essay'))::text,true);
select set_config('exam.essay_response',public.save_assessment_response(current_setting('exam.essay')::uuid,(select essay from exam_fixtures where label='essay'),'{"text":"Synthetic written work"}')::text,true);
select public.submit_assessment_attempt(current_setting('exam.essay')::uuid);
select public.decide_exam_retry((select schedule from exam_fixtures where label='essay'),'decline',(public.sync_exam_participation((select schedule from exam_fixtures where label='essay'))->>'revision')::bigint);
select pg_temp.ok(public.sync_exam_participation((select schedule from exam_fixtures where label='essay'))->>'grading_state'='pending','Finalized written paper remains under correction');
select pg_temp.denied($q$select public.get_assessment_results(current_setting('exam.essay')::uuid)$q$,'42501','Under correction has no final total');
select pg_temp.claim(2);
select pg_temp.denied($q$select public.finalize_assessment_grade(current_setting('exam.essay')::uuid)$q$,'23514','Supplied ungraded written answer blocks final grade');
select public.grade_assessment_response(current_setting('exam.essay_response')::uuid,2,'Synthetic feedback');
select public.finalize_assessment_grade(current_setting('exam.essay')::uuid);
select set_config('exam.graded_state',(public.get_exam_grading_detail(current_setting('exam.essay')::uuid)->'state')::text,true);
select pg_temp.ok(current_setting('exam.graded_state')::jsonb->>'grading_state'='complete' and current_setting('exam.graded_state')::jsonb->>'result_released'='false','Grading completion independent of release');
select pg_temp.denied('select score from public.assessment_attempts','42501','Staff uses checked RPC not shared role table grants');
select pg_temp.claim(5);
select pg_temp.denied($q$select public.get_assessment_results(current_setting('exam.essay')::uuid)$q$,'42501','Completed unreleased grade still protected');
select pg_temp.claim(2);
select public.release_exam_result((select schedule from exam_fixtures where label='essay'),'10000000-0000-0000-0000-000000000005',(current_setting('exam.graded_state')::jsonb->>'revision')::bigint);
select pg_temp.denied($q$select public.release_exam_review((select schedule from pg_temp.exam_fixtures where label='essay'),'10000000-0000-0000-0000-000000000005',(public.get_exam_grading_detail(current_setting('exam.essay')::uuid)->'state'->>'revision')::bigint)$q$,'23514','Review cannot release before schedule closes');
select pg_temp.denied($q$select public.grade_assessment_response(current_setting('exam.essay_response')::uuid,1)$q$,'42501','Released grade immutable');
select pg_temp.claim(5);
select pg_temp.ok((public.get_assessment_results(current_setting('exam.essay')::uuid)->>'score')::numeric=2,'Authorized released written total visible');
select pg_temp.ok(public.get_assessment_results(current_setting('exam.essay')::uuid)->'responses'->0->>'feedback' is null,'Written feedback gated by review');
select set_config('exam.essay_only',public.start_assessment_attempt((select schedule from exam_fixtures where label='essay_only'))::text,true);
select public.save_assessment_response(current_setting('exam.essay_only')::uuid,(select essay from exam_fixtures where label='essay_only'),'{"text":"Pending essay"}');
select public.submit_assessment_attempt(current_setting('exam.essay_only')::uuid);
select pg_temp.ok(public.sync_exam_participation((select schedule from exam_fixtures where label='essay_only'))->>'attempts_state'='finalized' and public.sync_exam_participation((select schedule from exam_fixtures where label='essay_only'))->>'grading_state'='pending','Essay not treated as objectively correct');
reset role;
-- Privileged persisted-state checks: omissions are real zero outcomes, not RLS-hidden rows.
select pg_temp.ok((select outcome='unanswered' and awarded_points=0 from private.assessment_question_outcomes where attempt_id=current_setting('exam.decline')::uuid),'Persisted unanswered outcome');
select pg_temp.ok((select count(*)=2 from public.assessment_attempts where participation_id=(select id from private.assessment_participations where schedule_id=(select schedule from exam_fixtures where label='accept'))),'Exactly two attempts persisted');
select pg_temp.ok((select count(*)=0 from public.assessment_responses where attempt_id=current_setting('exam.decline')::uuid),'No fabricated absent-response row');
select pg_temp.ok(not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='private' and p.prosecdef and not coalesce(p.proconfig,'{}') @> array['search_path=""']),'All private definers fixed search path');
select pg_temp.ok(not has_function_privilege('authenticated','public.create_organization(text,text)','EXECUTE'),'Migration 17 preserved');
select pg_temp.ok(not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='private' and (p.proname like '%\_v17' escape '\' or p.proname in ('lock_exam','exam_enrolled','valid_objective_key','auto_grade_attempt','refresh_exam_grade','finish_exam_attempt','reconcile_exam','exam_state')) and has_function_privilege('authenticated',p.oid,'EXECUTE')),'All v17 bypasses and internal evaluators inaccessible');
-- Real clock-based close: minimum duration is 60 seconds, but the schedule can
-- close sooner. Do not bypass immutable deadline triggers for expiry tests.
select pg_temp.fixture('expiry',2,60,false,clock_timestamp()+interval '500 milliseconds');
set local role authenticated;
select pg_temp.claim(5);
select set_config('exam.expired',public.start_assessment_attempt((select schedule from exam_fixtures where label='expiry'))::text,true);
select pg_sleep(0.6);
select pg_temp.denied($q$select public.save_assessment_response(current_setting('exam.expired')::uuid,(select q from pg_temp.exam_fixtures where label='expiry'),jsonb_build_object('option_ids',jsonb_build_array((select correct from pg_temp.exam_fixtures where label='expiry'))))$q$,'42501','Expired exam saves denied');
select pg_temp.ok(public.sync_exam_participation((select schedule from exam_fixtures where label='expiry'))->>'attempts_state'='finalized','Closed expired paper finalized without retry');
select pg_temp.ok((public.get_assessment_results(current_setting('exam.expired')::uuid)->>'score')::numeric=0,'Expired unanswered paper explicitly scores zero');
select public.submit_assessment_attempt(current_setting('exam.expired')::uuid);
select pg_temp.ok(public.sync_exam_participation((select schedule from exam_fixtures where label='expiry'))->>'retry_decision'='window_closed','Expiry state persists and refresh is stable');
reset role;
select pg_temp.ok((select status='graded' and submitted_at is not null from public.assessment_attempts where id=current_setting('exam.expired')::uuid),'Privileged verification of persisted expiry');
select pg_temp.fixture('blank_written',1,null,true);
set local role authenticated;
select pg_temp.claim(5);
select set_config('exam.blank',public.start_assessment_attempt((select schedule from exam_fixtures where label='blank_written'))::text,true);
select public.save_assessment_response(current_setting('exam.blank')::uuid,(select essay from exam_fixtures where label='blank_written'),'{"text":"   "}');
select public.submit_assessment_attempt(current_setting('exam.blank')::uuid);
select pg_temp.ok((public.get_assessment_results(current_setting('exam.blank')::uuid)->>'score')::numeric=0,'Blank subjective work scores zero without manual queue');
reset role;
select pg_temp.ok((select count(*)=2 and bool_and(awarded_points=0) from private.assessment_question_outcomes where attempt_id=current_setting('exam.blank')::uuid),'Entire blank paper accounted for');
select pg_temp.fixture('unused_retry',2,60,false,clock_timestamp()+interval '500 milliseconds');
set local role authenticated;
select pg_temp.claim(5);
select set_config('exam.unused',public.start_assessment_attempt((select schedule from exam_fixtures where label='unused_retry'))::text,true);
select public.submit_assessment_attempt(current_setting('exam.unused')::uuid);
select public.decide_exam_retry((select schedule from exam_fixtures where label='unused_retry'),'accept',(public.sync_exam_participation((select schedule from exam_fixtures where label='unused_retry'))->>'revision')::bigint);
select pg_sleep(0.6);
select pg_temp.ok(public.sync_exam_participation((select schedule from exam_fixtures where label='unused_retry'))->>'attempts_state'='finalized','Close forfeits accepted but unused retry');
select pg_temp.denied($q$select public.start_assessment_attempt((select schedule from pg_temp.exam_fixtures where label='unused_retry'))$q$,'42501','Closed accepted retry cannot start');
reset role;
select pg_temp.fixture('second_expiry',2,60,false,clock_timestamp()+interval '500 milliseconds');
set local role authenticated;
select pg_temp.claim(5);
select set_config('exam.first_expiry',public.start_assessment_attempt((select schedule from exam_fixtures where label='second_expiry'))::text,true);
select public.submit_assessment_attempt(current_setting('exam.first_expiry')::uuid);
select public.decide_exam_retry((select schedule from exam_fixtures where label='second_expiry'),'accept',(public.sync_exam_participation((select schedule from exam_fixtures where label='second_expiry'))->>'revision')::bigint);
select set_config('exam.second_expiry',public.start_assessment_attempt((select schedule from exam_fixtures where label='second_expiry'))::text,true);
select pg_sleep(0.6);
select pg_temp.ok(public.sync_exam_participation((select schedule from exam_fixtures where label='second_expiry'))->>'attempts_state'='finalized','Expired second paper finalizes');
select pg_temp.ok((public.get_assessment_results(current_setting('exam.second_expiry')::uuid)->>'score')::numeric=0,'Expired second paper total uses second answers');
reset role;
select pg_temp.fixture('pending_close',2,60,false,clock_timestamp()+interval '500 milliseconds');
set local role authenticated;
select pg_temp.claim(5);
select set_config('exam.pending_close',public.start_assessment_attempt((select schedule from exam_fixtures where label='pending_close'))::text,true);
select public.submit_assessment_attempt(current_setting('exam.pending_close')::uuid);
select pg_sleep(0.6);
select pg_temp.ok(public.sync_exam_participation((select schedule from exam_fixtures where label='pending_close'))->>'retry_decision'='window_closed','Close finalizes pending decision without inferred decline');
