set local role anon;
select pg_temp.denied('select public.get_exam_summaries(array[]::uuid[])','42501','Anonymous exam RPC denied');
select pg_temp.denied('select public.sync_exam_participation(gen_random_uuid())','42501','Anonymous sync denied');
reset role;
select count(*) as passed from exam_checks;
rollback;
